`var SK={skin:['乾性','油性','混合','中性','缺水','敏感','酒糟','其他'],marks:['細紋','斑','痘痘','泛紅','毛孔','暗沉','乾燥脫皮','其他'],concern:['細紋加深','斑點浮現','鬆弛下垂','毛孔粗大','敏感泛紅','暗沉','痘痘反覆','其他'],goals:['保濕','控油','提拉','亮膚','代謝','舒緩'],achieve:['更透亮','更水潤','毛孔變細','泛紅緩和','輪廓更緊','膚色均勻','其他']},MK=[],ML='',RXI=null,RXURL='https://saongx-code.github.io/pausespace/desk/su_rx.jpg';
