 function wrap(s,x,y,w,lh,sz,max){c.font=sz+'px '+F;c.fillStyle=INK;c.textBaseline='middle';var lines=[],cur='';String(s||'').split('').forEach(function(ch){if(ch==='\\n'){lines.push(cur);cur='';return}if(c.measureText(cur+ch).width>w){lines.push(cur);cur=ch}else cur+=ch});if(cur)lines.push(cur);if(lines.length>max){lines=lines.slice(0,max);lines[max-1]=lines[max-1].slice(0,-1)+'…'}lines.forEach(function(l,i){c.fillText(l,x,y+i*lh)})}
