 (before.marks||[]).forEach(function(m,i){c.fillStyle='rgba(200,107,74,.85)';c.beginPath();c.arc(m.x,m.y,13,0,7);c.fill();c.fillStyle='#fff';c.font='bold 18px '+F;c.textAlign='center';c.textBaseline='middle';c.fillText(String(i+1),m.x,m.y+1);c.textAlign='left';t(m.label,m.x+18,m.y,24,ACC)});
 t(rx.purpose||'',378,1356,26,INK,240);t(rx.achieve||'',378,1413,26,INK,240);
