 '<div class="slot"><b>療程項目</b><input type="text" id="svc" placeholder="例：酵素煥膚"></div>'}
function loadRx(cb){if(RXI&&RXI.complete&&RXI.naturalWidth)return cb();RXI=new Image();RXI.crossOrigin='anonymous';RXI.onload=cb;RXI.src=RXURL}
