function rxOf(id){var c=CASES.filter(function(x){return x.id===id})[0]||{};var rx=JSON.parse(JSON.stringify((c.draft||{}).rx||{}));RXF.forEach(function(k){var e=$('r_'+k[0]+'_'+id);if(e)rx[k[0]]=e.value.trim()});['inbodyBefore','inbodyAfter'].forEach(function(k,i){var e=$('ib'+i+'_'+id);if(e)rx[k]=e.value.split(/[,，、\\s]+/).filter(Boolean)});return rx}
