  {label:'現在的皮膚狀態',done:function(){return false},keep:1,body:function(){return '<div class="sub2">先選一種，再點臉上的位置</div>'+chipsH('mk',SK.marks)+'<canvas id="face" style="width:100%;max-width:320px;display:block;margin:8px auto;border-radius:12px"></canvas><div class="thumbs" id="mkl"></div><button type="button" class="chip" data-undo="1">↩ 取消上一個點</button>'},skip:'沒有要標的'},
